import re, os
files = ["AGENTS.md","custom.md","custom-family.md","TODO.md"] + sorted("agent-data/"+f for f in os.listdir("agent-data") if f.endswith('.md')) + ["notes/chores/chores-16.md","notes/dogfood.md","notes/todo-backlog.md","notes/bugs.md"]
def slug(h):
    h = h.strip().lstrip('#').strip().replace('**','').replace('`','')
    out = []
    for c in h.lower():
        if c.isalnum() or c in '-_': out.append(c)
        elif c == ' ': out.append('-')
    return ''.join(out)
anchors = {}
def get_anchors(f):
    if f in anchors: return anchors[f]
    a = set(); fen = False
    for l in open(f):
        if l.startswith('```'): fen = not fen; continue
        if not fen and re.match(r'#{1,6} ', l): a.add(slug(l))
    anchors[f] = a
    return a
bad = []
for f in files:
    fence = False
    for n, line in enumerate(open(f), 1):
        if line.startswith('```'): fence = not fence; continue
        if fence: continue
        for m in re.finditer(r'\]\((/?[^)\s]+)\)', line):
            t = m.group(1)
            if t.startswith('http') or '<' in t or t.endswith('#...'): continue
            path, _, frag = t.partition('#')
            if path.startswith('/'): target = path.lstrip('/')
            else: target = os.path.normpath(os.path.join(os.path.dirname(f), path)) if path else f
            if path and not os.path.exists(target):
                bad.append(f"{f}:{n}: missing file {t}"); continue
            if frag and target.endswith('.md') and frag not in get_anchors(target):
                bad.append(f"{f}:{n}: missing anchor {t}")
print('\n'.join(bad) if bad else 'check 1 PASS: all links resolve')
